/* Generated by equipe-design emit — do not edit by hand; change the tokens and emit again. */
@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

@theme {
  /* colour roles: bg-background, text-text, border-border … */
  --color-background: #ffffff;
  --color-surface: #f7f7f7;
  --color-raised: #fafafa;
  --color-text: #1a1a1a;
  --color-muted-text: #717171;
  --color-primary: #2b2b2b;
  --color-on-primary: #ffffff;
  --color-secondary: #f1f1f1;
  --color-accent: #2456c9;
  --color-border: #e1e1e1;
  --color-border-strong: #818181;
  --color-ring: #2b2b2b;
  --color-destructive: #c62828;
  --color-success: #1b7a43;
  --color-warning: #8f5b00;

  /* palette: bg-teal-600 … (the step is lightness, 0 light to 1000 dark) */
  --color-neutral-0: #ffffff;
  --color-neutral-25: #f7f7f7;
  --color-neutral-50: #fafafa;
  --color-neutral-75: #f1f1f1;
  --color-neutral-100: #e1e1e1;
  --color-neutral-125: #eeeeee;
  --color-neutral-150: #f2f2f2;
  --color-neutral-325: #9a9a9b;
  --color-neutral-375: #8b8b8b;
  --color-neutral-400: #818181;
  --color-neutral-450: #717171;
  --color-neutral-700: #2b2b2b;
  --color-neutral-725: #29292b;
  --color-neutral-750: #26262a;
  --color-neutral-775: #1a1a1a;
  --color-neutral-800: #1d1d1f;
  --color-neutral-825: #111113;
  --color-neutral-850: #2e2e2f;
  --color-neutral-975: #000000;
  --color-yellow-200: #e8b44a;
  --color-yellow-475: #8f5b00;
  --color-blue-250: #8ab0ff;
  --color-blue-500: #2456c9;
  --color-orange-275: #ff7b72;
  --color-orange-450: #c62828;
  --color-green-275: #4cc38a;
  --color-green-500: #1b7a43;

  /* fonts */
  --font-sans: 'Hanken Grotesk', Pretendard, 'Noto Sans KR', sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, monospace;

  /* radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 10px;
  --radius-full: 9999px;

  /* type roles: text-body, text-h1 … */
  --text-display: 40px;
  --text-display--line-height: 1.25;
  --text-display--letter-spacing: -0.01em;
  --text-display--font-weight: 600;
  --text-h1: 33px;
  --text-h1--line-height: 1.25;
  --text-h1--letter-spacing: -0.01em;
  --text-h1--font-weight: 600;
  --text-h2: 28px;
  --text-h2--line-height: 1.25;
  --text-h2--letter-spacing: -0.01em;
  --text-h2--font-weight: 600;
  --text-h3: 23px;
  --text-h3--line-height: 1.25;
  --text-h3--letter-spacing: -0.01em;
  --text-h3--font-weight: 600;
  --text-body: 16px;
  --text-body--line-height: 1.6;
  --text-body--letter-spacing: 0em;
  --text-body--font-weight: 400;
  --text-small: 13px;
  --text-small--line-height: 1.6;
  --text-small--letter-spacing: 0em;
  --text-small--font-weight: 400;
  --text-mono: 13px;
  --text-mono--line-height: 1.6;
  --text-mono--letter-spacing: 0em;
  --text-mono--font-weight: 400;

  /* shadow */
  --shadow-1: 0px 4px 14px 0px #0000001a;

  /* motion */
  --duration-fast: 140ms;
  --duration-base: 240ms;
  --duration-slow: 400ms;
  --ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
}

.dark {
  --color-background: #111113;
  --color-surface: #1d1d1f;
  --color-raised: #29292b;
  --color-text: #eeeeee;
  --color-muted-text: #9a9a9b;
  --color-primary: #f2f2f2;
  --color-on-primary: #000000;
  --color-secondary: #26262a;
  --color-accent: #8ab0ff;
  --color-border: #2e2e2f;
  --color-border-strong: #8b8b8b;
  --color-ring: #f2f2f2;
  --color-destructive: #ff7b72;
  --color-success: #4cc38a;
  --color-warning: #e8b44a;
}
